import requests


def make_embeddings_request(text: str) -> dict:
    url = 'https://api.directembeddings.com/v1/embeddings'
    headers = {
        'Authorization': f'Bearer YOUR_API_KEY',
        'Content-Type': 'application/json'
    }
    payload = {
        'input': text,
        'model': 'direct-embeddings-v1'
    }
    try:
        response = requests.post(url, headers=headers, json=payload)
        response.raise_for_status()
        return response.json()
    except requests.RequestException as e:
        print(f'Error making embeddings request: {e}')
        return {}


def normalize_embeddings_response(response: dict) -> list:
    if 'data' in response:
        return [item['embedding'] for item in response['data']]
    return []

import boto3
import numpy as np

def get_embedding(text):
    bedrock = boto3.client('bedrock')
    response = bedrock.invoke_model(
        model_id='amazon.titan-embed-text-v1',
        body={
            'inputText': text
        }
    )
    embedding = response['embedding']
    return np.array(embedding)

def cosine_similarity(vec1, vec2):
    dot_product = np.dot(vec1, vec2)
    norm_vec1 = np.linalg.norm(vec1)
    norm_vec2 = np.linalg.norm(vec2)
    return dot_product / (norm_vec1 * norm_vec2)

def compute_similarity(text1, text2):
    embedding1 = get_embedding(text1)
    embedding2 = get_embedding(text2)
    return cosine_similarity(embedding1, embedding2)

import boto3

def generate_embeddings(texts):
    bedrock = boto3.client('bedrock-runtime')
    embeddings = []
    for text in texts:
        response = bedrock.invoke_model(
            model_id='amazon.titan-embed-text-v1',
            body={
                'inputText': text
            }
        )
        embeddings.append(response['embedding'])
    return embeddings

if __name__ == '__main__'):
    texts = ['sample text 1', 'sample text 2']
    embeddings = generate_embeddings(texts)
    print(embeddings)
